import ResumeUpload from "../components/ResumeUpload";
import { useSearchParams } from "react-router-dom";

function UploadPage() {
  const [searchParams] = useSearchParams();
  const jobId = searchParams.get('jobId');

  return (
    <div className="page mt-10">
      <div className="container">
        <div className="max-w-4xl mx-auto">
          <div className="upload-grid">
            <div className="card">
              <h2 className="text-2xl mb-4">Upload Your Resume</h2>
              {jobId && (
                <div className="mb-4">
                  <span className="badge bg-primary">Applying for Job ID: {jobId}</span>
                </div>
              )}
              <p className="muted mb-6">Our AI will analyze your skills, calculate a match score, and provide instant feedback on your eligibility.</p>

              <div className="features-mini">
                <div className="feature-item">
                  <strong> formats:</strong> .pdf, .docx, .txt
                </div>
                <div className="feature-item">
                  <strong> analysis:</strong> Skill extraction & scoring
                </div>
                <div className="feature-item">
                  <strong> feedback:</strong> Identification of skill gaps
                </div>
              </div>
            </div>

            <div className="card">
              <ResumeUpload jobId={jobId} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default UploadPage;
